const TOOL_NAMES = TOOLS.map((t) => t.name);

/** OpenAI 兼容 tool calling 的 tools 字段。 */
function openAiTools() {
  return TOOLS.map((t) => ({
    type: 'function',
    function: {
      name: t.name,
      description: t.description,
      parameters: t.inputSchema,
    },
  }));
}

